INSERT INTO macro_core.phase_call (id, asset, week, phase, phase_name, prior_phase, direction, reason, evidence, falsifier, status, authored_at, activated_at, superseded_by)
VALUES ('bca353ed-2546-5453-9e70-f3964aa29468', 'crypto', '2026-W32', 5, 'Lull / Base-Building', 5, 'unchanged', 'the $62-66K box held a fourth week and no key level broke on a close - but the composition deteriorated for the first time, with BTC falling 3.9% into the most risk-on equity tape in months and the ETF streak breaking to outflow', ARRAY['The level held and the character inverted. Crypto spent four weeks absorbing shocks; this week it was handed the opposite - a +1% equity week, a 16-handle VIX, oil collapsing and September hike odds falling - and sold off anyway. Failing to react to good news is a different, worse signal than absorbing bad news.', 'The four-week ETF arc completed into outflow, with a −$265.4M single day on Jul 31. The one flow that had been actively confirming the floor is now working against it, and stablecoins and DeFi TVL offered no offset.', 'Positioning remains the single clean condition: funding is near-neutral across 806 Binance perps, with the negative tail confined to illiquid smallcaps and the richest positive funding sitting in tokenized equity perps. There is no crowded crypto long to unwind.', '↳ coin-denominated OI rose 1,614,388 → 1,657,612 BTC (+2.7%) while price fell 3.9%; the USD figure fell only because BTC did. Leverage building into a falling tape is how a Lull ends downward rather than sideways.']::text[], 'Up to Phase 1 - a weekly close above $66K on rising volume with the ETF flow turning green again; the band has now rejected four times, so a fifth attempt needs volume the Lull has not supplied. Down to Phase 4 - a daily close below $62K that is not reclaimed within two sessions, with ETF outflows compounding. That is the "key levels keep breaking" leg, and after the Aug 1 sweep to ~$62.2K it is closer than at any point in four weeks.', 'superseded', TIMESTAMPTZ '2026-08-03T00:00:00Z', TIMESTAMPTZ '2026-08-03T00:00:00Z', NULL)
