INSERT INTO macro_core.phase_call (id, asset, week, phase, phase_name, prior_phase, direction, reason, evidence, falsifier, status, authored_at, activated_at, superseded_by)
VALUES ('fd820463-9594-5bcb-ae3c-a312329e1e7d', 'equities', '2026-W32', 3, 'Late Cycle / Distribution', 3, 'unchanged', 'the index gained 1.05% while breadth rolled over inside the same week, leadership compressed to two names and credit widened a second consecutive time - internals decaying under a rising index, with none of the four Stage-4 conditions met', ARRAY['The week''s gain was manufactured by two names. Microsoft''s ~$450B single-day add and Amazon''s AWS reacceleration carried the S&P and the Nasdaq, while the Russell managed +0.05% and breadth ended lower than it started. Cap-weight beating equal-weight on a narrowing base is Stage 3''s textbook definition, not Stage 2''s.', 'Leadership did not broaden, it fractured. The AI complex split into monetisers and spenders in a single session, which leaves the index resting on fewer names than it did before the week - the opposite of what a healthy re-rate looks like.', 'Credit and rate vol are the only honest confirmations on the board: HY OAS widened a second straight week and MOVE hit the highest print of the run, while VIX collapsed to 15.99. Spot vol low, hedging demand rising, spreads quietly widening - three of the four lines in Stage 3''s own classification list.', '↳ SLOOS prints 14:00 ET today, so condition 3 below is gradeable tonight.']::text[], 'Down to Stage 4 - HY OAS holding above ~300 bps for two consecutive weeks with SLOOS showing broad tightening, and breadth under 60% with the S&P losing its rising 200dma at 7,024. Up to Stage 2 - breadth back above 70% and sustained two weeks with the Russell participating and equal-weight leading, which is precisely what this week refused to deliver.', 'superseded', TIMESTAMPTZ '2026-08-03T00:00:00Z', TIMESTAMPTZ '2026-08-03T00:00:00Z', NULL)
