INSERT INTO macro_core.phase_call (id, asset, week, phase, phase_name, prior_phase, direction, reason, evidence, falsifier, status, authored_at, activated_at, superseded_by)
VALUES ('01179927-e368-538e-ab53-6e42bcc3dc3c', 'crypto', '2026-W34', 5, 'Lull / Base-Building', 5, 'unchanged', 'the box held a sixth week - but the failed $65K breakout on the best inflow week since April is distribution inside the box, the worst composition signal of the run', ARRAY['Price sat out a fortnight in which equities hit records, gold hit records and the hike tail died - the summer''s strongest risk-on impulse produced +0.95% per Snapshot.', 'The flow whipsaw per Snapshot: a five-green-sessions +$853.5M week failed at $65K, then reversed to a six-week-worst outflow while ETH''s streak snapped - good news is being sold, not absorbed.', 'The Aug 13-15 flush cleared the W32 coin-terms leverage build without breaking $62K per Snapshot - the box is intact but now tested from both sides, and the Coldcard exploit (What Changed) chips at the self-custody layer behind it.']::text[], 'up - a weekly close over $66K with green ETF flow that same week (the +$853.5M failure is proof flow-less breaks don''t count); down - a daily close under $62K now that the flush has already cleared leverage, which would be weakness with nothing left to blame and opens $58-60K.', 'superseded', TIMESTAMPTZ '2026-08-17T00:00:00Z', TIMESTAMPTZ '2026-08-17T00:00:00Z', NULL)
