INSERT INTO macro_core.phase_call (id, asset, week, phase, phase_name, prior_phase, direction, reason, evidence, falsifier, status, authored_at, activated_at, superseded_by)
VALUES ('3b51f2a3-bcb4-5976-9e68-ebfd76d4e7e4', 'equities', '2026-W34', 3, 'Late Cycle / Distribution', 3, 'unchanged', 'was Phase 3 last week; unchanged, but this is the weakest the call has been: every internals leg of the distribution case reversed over the fortnight, and the call now rests on the macro/policy layer plus the beats-sold tell', ARRAY['The record run came with breadth repair, small-cap confirmation and credit re-tightening per Snapshot - Stage-2 behavior, not distribution decay.', 'The macro layer still reads late-cycle: a hold-vs-hike Fed with three hike dissents, sticky 3.4% inflation, the first payroll contraction of the cycle plus the retail-sales and UMich cracks per What Changed - growth is not "resilient" and policy is not supportive, which Stage 2 requires.', 'Reward-per-beat is shrinking at the leaders (AMD, Cisco, AMAT all sold on beats) while term premium reprices at record auction yields on a $739B borrowing quarter - the two late-cycle tells that did not reverse.']::text[], 'NVDA bought on its Aug 26 print + core PCE ≤0.2% the same day + breadth holding >70% through the Sep 4 NFP → reclassify to Stage 2 Expansion (and the exposure band lifts with it). Conversely, the first soft print the tape sells flips the regime read the other way and puts the 3→4 watch back on.', 'superseded', TIMESTAMPTZ '2026-08-17T00:00:00Z', TIMESTAMPTZ '2026-08-17T00:00:00Z', NULL)
