INSERT INTO macro_core.phase_call (id, asset, week, phase, phase_name, prior_phase, direction, reason, evidence, falsifier, status, authored_at, activated_at, superseded_by)
VALUES ('f20811a6-770a-5683-bb9d-fc7690a81e2a', 'crypto', '2026-W35', 1, 'Early Bull', 5, 'up', 'the falsifier W34 itself named — a flow-confirmed reclaim — fired in full, taking the 5→1 tracker from 1-of-4 to 4-of-4 in five sessions', ARRAY['The break was not a drift: six weeks of range cleared in five sessions to a three-month high, with the old box top now the structure to defend rather than the ceiling to test.', 'The move was funded by trapped shorts, not new longs — dollar OI rose 21% while coin-terms OI fell 0.9% per Snapshot, and majors'' funding sits exactly at the neutral baseline after a 20-30% rally.', 'Flow and news-reaction both confirmed independently: the year''s biggest ETF week on five consecutive green days with an accelerating ETH sequence, and an 11.5% BTC move off a merely revived — not passed — CLARITY Act, which is the "sharp reaction to partial good news" condition by definition.', '↳ The Sep 15 CLARITY procedural vote is a hard, dated binary that lands one day before the FOMC — it is the single largest scheduled risk to this upgrade, and the narrative half of the move is entirely contingent on it.', '↳ Tension worth naming: F&G at 73 is not Early Bull "disbelief" psychology. Sentiment is chasing while positioning is not — that gap resolves either by money following (confirmation) or by sentiment snapping back (a 42-point round trip).']::text[], 'A weekly close back inside the old $62-66K box says the entire move was a squeeze and the Lull call was right; short of that, a failure to hold $66-70K on the first retest downgrades this to "watching" without restoring Phase 5.', 'superseded', TIMESTAMPTZ '2026-08-24T00:00:00Z', TIMESTAMPTZ '2026-08-24T00:00:00Z', NULL)
