INSERT INTO macro_core.phase_call (id, asset, week, phase, phase_name, prior_phase, direction, reason, evidence, falsifier, status, authored_at, activated_at, superseded_by)
VALUES ('859659f5-20c8-5954-a905-28fd9d7dc9c1', 'equities', '2026-W35', 3, 'Late Cycle / Distribution', 3, 'unchanged', 'was Phase 3 last week; unchanged, but the call is materially stronger than it was — after a fortnight resting on the macro layer alone, the internals came back to the distribution side in a single week', ARRAY['The textbook Stage-3 tell fired on the consumer bellwether: Walmart beat on both lines and raised its sales guide, and still lost 9% on a guidance rounding error — beats rewarded less, misses punished more.', 'Every internals leg that inverted during the W32-W34 melt-up turned back: breadth gave up half its repair, HY and IG both widened off the low, and VIX and MOVE lifted off run-lows together.', 'Leadership narrowed by destruction rather than rotation — the semis de-rated 5% on no catalyst eight sessions before NVDA reports, while the Dow outperformed absorbing a 9% drawdown in its largest staple.', '↳ Warsh''s Aug 28 keynote and the Aug 26 PCE/NVDA double-header both land inside seven sessions; neither can upgrade the phase, but a hawkish-credible Warsh plus a sold NVDA beat is the cleanest path to condition 4 confirming.']::text[], 'A close below 7,500 confirmed by breadth <65% and HY >290 bps opens the 3→4 transition. In the other direction, a new record close on breadth >72% with HY back under 265 bps revives the Stage-2 reclassification W34 flagged — this week killed that case, it did not bury it.', 'superseded', TIMESTAMPTZ '2026-08-24T00:00:00Z', TIMESTAMPTZ '2026-08-24T00:00:00Z', NULL)
