INSERT INTO macro_core.phase_call (id, asset, week, phase, phase_name, prior_phase, direction, reason, evidence, falsifier, status, authored_at, activated_at, superseded_by)
VALUES ('62394439-7a82-509f-bf4d-0658d609e238', 'crypto', '2026-W36', 1, 'Early Bull', 1, 'unchanged', 'This was Phase 1 last week and remains unchanged because the breakout held with lighter leverage and positive fund demand, but majors did not extend and BTC''s inflow streak broke.', ARRAY['BTC held the reclaimed range while aggregate open interest declined in both dollars and coin terms.', 'BTC and ETH ETFs remained net positive, with ETH demand accelerating despite the Friday macro reversal.', 'Sentiment cooled from its W35 spike, but alt breadth fell to the Bitcoin-season threshold.']::text[], 'Phase 2 needs BTC to hold above the reclaimed structure, majors to resume impulsive breadth, and a liquidation dip to be bought; a weekly loss of $70K with ETF outflows would reverse the Phase 1 call. Sep 15 CLARITY cloture is the dated catalyst.', 'superseded', TIMESTAMPTZ '2026-08-31T00:00:00Z', TIMESTAMPTZ '2026-08-31T00:00:00Z', NULL)
