INSERT INTO macro_core.phase_call (id, asset, week, phase, phase_name, prior_phase, direction, reason, evidence, falsifier, status, authored_at, activated_at, superseded_by)
VALUES ('ab417104-5652-5d7b-a569-d700e10fe958', 'equities', '2026-W36', 3, 'Late Cycle / Distribution', 3, 'unchanged', 'This was Phase 3 last week and remains unchanged because restrictive policy and internal divergence persist, while credit and volatility reject contraction.', ARRAY['Headline indexes rose, but Russell lost ground and S&P breadth softened per Snapshot.', 'NVIDIA reset the earnings bar, while Marvell showed that an ordinary beat-and-raise still gets punished.', 'Asset managers remain heavily long as leveraged funds rebuild shorts, leaving a fragile positioning split into labor data.']::text[], 'A sustained breadth expansion above 75%, tighter or stable credit, and rewarded non-megacap earnings would reopen Phase 2; a falling 200dma plus breadth below 50%, HY OAS above 300 bps, and rising VIX/MOVE would force Phase 4.', 'superseded', TIMESTAMPTZ '2026-08-31T00:00:00Z', TIMESTAMPTZ '2026-08-31T00:00:00Z', NULL)
