INSERT INTO macro_core.phase_call (id, asset, week, phase, phase_name, prior_phase, direction, reason, evidence, falsifier, status, authored_at, activated_at, superseded_by)
VALUES ('bd683f1d-dcb4-59ab-913a-397171a1ab82', 'crypto', '2026-W37', 1, 'Early Bull', 1, 'unchanged', 'sponsorship and sentiment advanced while price stayed capped, so the impulse that defines Phase 2 has still not arrived', ARRAY['BTC completed a full Waller-to-payrolls round trip inside three sessions and was rejected at $82K for the third time, which is a level acting as a gate rather than a base.', 'A third straight positive ETF week concentrated into one session and into BTC alone, while ETH fund demand fell nearly three quarters and its no-outflow streak broke.', 'Open interest rebuilt 9% in coin terms with funding still near flat and the week''s largest liquidation event 87% shorts, so leverage is returning against the cap, not with it.']::text[], 'A daily close above $82,000 that holds a retest with ETF flows still positive confirms the impulse and puts Phase 2 in play; a weekly close under $74K with ETF outflows sends it back to Phase 5. The Sep 15 CLARITY cloture and the Sep 16 dots are the two dated conditions that could settle it inside the grading window.', 'superseded', TIMESTAMPTZ '2026-09-09T00:00:00Z', TIMESTAMPTZ '2026-09-09T00:00:00Z', NULL)
