INSERT INTO macro_core.phase_call (id, asset, week, phase, phase_name, prior_phase, direction, reason, evidence, falsifier, status, authored_at, activated_at, superseded_by)
VALUES ('25a5751e-eb4f-5b50-9b59-68a762700550', 'equities', '2026-W37', 3, 'Late Cycle / Distribution', 3, 'unchanged', 'the index held flat while every internal it depends on deteriorated, and credit still refuses to confirm a contraction', ARRAY['The index went nowhere while breadth fell for a third straight week through its long-run mean and CNN F&G dropped into Fear, which is the textbook distribution divergence rather than a rotation.', 'Broadcom''s record quarter and raised multi-year targets were not paid and Lululemon was punished 20% for a guidance cut, so beats are rewarded less and misses punished more.', 'Asset managers trimmed marginally while leveraged funds declined to cover into strength, leaving the positioning split intact through a live FOMC.']::text[], 'Breadth sustained above 72% with a non-megacap beat actually rewarded reopens Phase 2; a close below the rising 200dma with breadth under 50%, HY through 300 bps and a rising VIX and MOVE forces Phase 4. Aug CPI on Sep 11 and the Sep 15–16 dots are the dated settlers, and neither has landed yet.', 'superseded', TIMESTAMPTZ '2026-09-09T00:00:00Z', TIMESTAMPTZ '2026-09-09T00:00:00Z', NULL)
