INSERT INTO macro_core.phase_call (id, asset, week, phase, phase_name, prior_phase, direction, reason, evidence, falsifier, status, authored_at, activated_at, superseded_by)
VALUES ('b120caaa-11ac-57cc-84d2-acf611e09fbe', 'crypto', '2026-W38', 1, 'Early Bull', 1, 'unchanged', 'BTC held above the $74K falsifier, but the flow support behind the call reversed and the tracker fell back', ARRAY['BTC failed at $80K without ever testing the $82K gate and printed a two-week low, while ETH broke to a January high and faded: the only impulse in the complex did not hold.', 'BTC ETF flows reversed to four straight outflow sessions while ETH funds took the week''s only meaningful inflow, so sponsorship rotated rather than broadened.', 'Crypto F&G gave back its whole Waller rebuild and OI trimmed slightly with funding flat, which is de-risking without a liquidation flush to scoop.']::text[], 'A weekly BTC close under $74K with a second outflow week sends the call to Phase 5 Lull; a daily close above $82,000 that holds its retest with BTC ETF flows back positive restores the 1 → 2 path. The Sep 15 CLARITY motion and the Sep 16 dots both land inside the grading window.', 'superseded', TIMESTAMPTZ '2026-09-14T00:00:00Z', TIMESTAMPTZ '2026-09-14T00:00:00Z', NULL)
