INSERT INTO macro_core.phase_call (id, asset, week, phase, phase_name, prior_phase, direction, reason, evidence, falsifier, status, authored_at, activated_at, superseded_by)
VALUES ('9a83dbe1-be67-5da0-8c31-8714e1fab76a', 'equities', '2026-W38', 3, 'Late Cycle / Distribution', 3, 'unchanged', 'internals decayed sharply while price, credit and vol all stayed far from contraction', ARRAY['Breadth broke 60% and CNN F&G fell deeper into Fear while the S&P lost under 1%, and the Russell took more than three times the index loss: the decline is broadening beneath a cap-weighted shell.', 'Oracle''s beat faded and memory reversed from a record on a single model release, so beats are rewarded less and narrative shocks punish the crowded leg immediately.', 'Asset managers cut their ES overlay for a second week and leveraged funds added shorts, while MOVE jumped and HY widened only modestly: positioning is de-grossing ahead of stress rather than in response to it.']::text[], 'Phase 4 needs three of four: an S&P close below 7,450 that fails a retest, breadth under 45%, HY above 300 bps, and VIX above 22 with MOVE above 90. Breadth back above 65% with a rewarded AI beat reopens the Phase 2 question. The Sep 16 dots and the Sep 18 quad witching are the dated settlers.', 'superseded', TIMESTAMPTZ '2026-09-14T00:00:00Z', TIMESTAMPTZ '2026-09-14T00:00:00Z', NULL)
