INSERT INTO macro_core.phase_call (id, asset, week, phase, phase_name, prior_phase, direction, reason, evidence, falsifier, status, authored_at, activated_at, superseded_by)
VALUES ('51f0a9c9-e21e-58ed-8134-518edaba1e4a', 'crypto', '2026-W39', 1, 'Early Bull', 1, 'unchanged', 'price and sentiment both confirmed but the fund-flow condition the call has rested on for three weeks still has not', ARRAY['BTC defended the $74K falsifier on FOMC day and then cleared the $80K level that had rejected it twice, in the same week the Fed hiked and the CLARITY Act died, so the move cannot be read as a rates trade.', 'The regulatory driver moved from Congress to the SEC inside 48 hours, and SOL, whose chain already carries roughly $465m of tokenised stock, led the majors while BTC dominance fell.', 'The impulse was squeeze-shaped rather than flow-shaped: eight shorts liquidated for every long, open interest rebuilt with funding flat, and the ETF week finished at a rounding error while ETH''s four-week inflow streak snapped.']::text[], 'Phase 2 needs the flow condition — a BTC ETF inflow week above roughly +$500M with the streak intact — alongside BTC accepting above $82K. A close back under $76K that breaks the Sep 15 low puts the $74K falsifier live again and reopens the Phase 5 question. The Oct 1 MiCA consultation close and the Oct 20 SEC comment deadline are the dated regulatory settlers.', 'active', TIMESTAMPTZ '2026-09-21T00:00:00Z', TIMESTAMPTZ '2026-09-21T00:00:00Z', NULL)
