VALUES ('06a7a4bc-96bd-5372-850e-73cc9eab8158', 'equities', '2026-W39', 3, 'Late Cycle / Distribution', 3, 'unchanged', 'the internals deteriorated again while every contraction condition moved further away', ARRAY['Breadth broke 50% for the first time in this arc and the Dow took a third straight losing week while the S&P finished flat and the Nasdaq alone rose: index-level calm on a visibly narrowing base is the Phase 3 signature, not a Phase 4 one.', 'Leadership compressed to a single trade. Memory and AI infrastructure carried the Nasdaq on Intel''s capacity warning, and UBS''s capex arithmetic now routes nine in ten incremental AI dollars through memory, so one Sep 30 print carries the index''s only working leg.', 'Positioning churned rather than accumulated: asset managers cut the ES overlay by the largest step of the arc while leveraged funds covered shorts into the same meeting, which is two crowds leaving opposite sides at once, not a bid arriving.']::text[], 'Phase 4 needs three of four — an S&P close below 7,450 that fails its retest, breadth under 45%, HY above 300 bps, and VIX above 22 with MOVE above 90. Breadth back above 60% with the Russell confirming reopens the Phase 2 question. The Sep 22–24 auction cluster and Micron on Sep 30 are the dated settlers.', 'active', TIMESTAMPTZ '2026-09-21T00:00:00Z', TIMESTAMPTZ '2026-09-21T00:00:00Z', NULL)
ON CONFLICT (id) DO UPDATE SET
    phase = EXCLUDED.phase,
    phase_name = EXCLUDED.phase_name,
    prior_phase = EXCLUDED.prior_phase,
    direction = EXCLUDED.direction,
    reason = EXCLUDED.reason,
    evidence = EXCLUDED.evidence,
    falsifier = EXCLUDED.falsifier,
    status = EXCLUDED.status,
    authored_at = EXCLUDED.authored_at,
    activated_at = EXCLUDED.activated_at,
    superseded_by = EXCLUDED.superseded_by;
