-- scenario_set, scenario, trigger_clause, scenario_target.
-- Three scenarios summing to 100 is the other deferred constraint
-- trigger, so a whole set is written inside one transaction.
BEGIN;
INSERT INTO macro_core.scenario_set (id, week, synthesis, probability_check, swing_variables, rules_waived, status, authored_at, activated_at, superseded_by)
VALUES ('546b24b5-bbd2-589d-988c-5066aab04691', '2026-W32', 'The week that was supposed to be about the Fed and the hyperscalers turned out to be about neither: it was about a $9 collapse in Brent on a Hormuz reopening framework, and about the AI trade splitting into two factors that no longer move together. Both changes pull the market''s dominant driver out of the macro column and into the micro one, because with oil falling and the front end pricing less Fed, the September hike case is losing the input it was built on, while a 30Y at 2007 highs says the bond market is repricing term premium rather than policy. This is a relative-value tape inside a distribution regime, and the two things that can turn it back into a directional one are this afternoon''s SLOOS and the labour block that runs Tuesday through Friday. Crypto is the outlier worth watching: it fell through a tape designed to lift it, which matters more than the level it managed to hold.', NULL, '["The Hormuz reopening framework into the ~Aug 16 MoU expiry: ratified or merely holding = Brent works toward $75-80, the September hike case built on oil pass-through loses its foundation, the Aug 12 CPI \"reversal\" thesis dies and the energy overweight becomes the wrong side / Iran repudiates it (Mehr already has) and strikes resume = Brent back over $90 within a session and the whole week''s rate repricing unwinds. Size for a headline that can invert intraday.","The labour block against a 66% September hike (JOLTS Aug 4, ISM Services Aug 5, NFP Aug 7): hot payrolls or wages = the odds that just fell from 82% re-arm and the 30Y at 5.21% has no cap / soft = a 1.5% GDP print plus a −0.1% headline PCE month becomes a hold case, but the relief steepens the curve rather than easing financial conditions.","Whether the monetiser/spender split extends from hyperscalers to silicon (AMD Aug 4, TSMC Aug 10, NVDA Aug 26): AMD shows bookings behind the capex = the semis leg that ripped 8-18% is a re-rate with a floor / AMD guides on roadmap rather than revenue = the sellers of silicon get reclassified as spenders too, and the SOX gains give back fast.","China''s DUV path against Samsung''s \"shortage to 2028\": the memory trade now has two clocks running against each other and only one of them is priced.","↳ watch CXMT DRAM output guidance and ASML''s China order book, not the DRAM spot price - the spot price is the trade that already worked."]'::jsonb, ARRAY[]::int[], 'superseded', TIMESTAMPTZ '2026-08-03T00:00:00Z', TIMESTAMPTZ '2026-08-03T00:00:00Z', NULL)
ON CONFLICT (id) DO UPDATE SET
    synthesis = EXCLUDED.synthesis,
    probability_check = EXCLUDED.probability_check,
    swing_variables = EXCLUDED.swing_variables,
    rules_waived = EXCLUDED.rules_waived,
    status = EXCLUDED.status,
    authored_at = EXCLUDED.authored_at,
    activated_at = EXCLUDED.activated_at,
    superseded_by = EXCLUDED.superseded_by;
