INSERT INTO macro_core.scenario_set (id, week, synthesis, probability_check, swing_variables, rules_waived, status, authored_at, activated_at, superseded_by)
VALUES ('5a019daa-56d0-50ee-9997-68e173b7cb8a', '2026-W34', 'The September hike died in a fortnight - a payroll contraction plus in-line CPI and flat PPI took FedWatch from two-thirds hike to two-thirds hold - and removing that tail, not easing, is what re-rated equities to records with repaired breadth. The same prints fattened the opposite tail: hard data is cracking (payrolls, retail, sentiment) while the long end charges record auction yields for a $739B quarter and gold rips to records on a bid that survived the war news improving. The game this week is whether soft data stays Fed-friendly or tips into a growth scare, with Aug 26 - PCE and NVDA on the same day - as the pivot, and post-MoU Iran as a live oil tail in both directions.', NULL, '["Whether bad news stays good news (IP Aug 18, JOLTS Sep 1, NFP Sep 4): mildly soft = hold-fuel and the melt-up grinds on / an outright contraction the tape sells = the regime flipped, and Friday''s bought retail-sales miss was the dress rehearsal for that test.","The Aug 26 double-header: core PCE ≤0.2% + NVDA bought = the Stage-2 reclassification completes / core ≥0.3% or NVDA sold on a beat = the hike debate re-arms into the SEP and the reward-per-beat decay goes systemic.","Post-MoU Iran: \"unprecedented\" US measures or another tanker strike = Brent breaks $92 and re-imports inflation / resumed talks = the war bid drains and gold finally shows how much of its +8% was debasement rather than war.","The vol floor into Aug 21 OpEx: VIX at run-lows with CNN F&G in Greed is the first time this run that vol and sentiment lean the same crowded way - a gamma unpin is the cheap tail on any of the above."]'::jsonb, ARRAY[]::int[], 'superseded', TIMESTAMPTZ '2026-08-17T00:00:00Z', TIMESTAMPTZ '2026-08-17T00:00:00Z', NULL)
ON CONFLICT (id) DO UPDATE SET
    synthesis = EXCLUDED.synthesis,
    probability_check = EXCLUDED.probability_check,
    swing_variables = EXCLUDED.swing_variables,
    rules_waived = EXCLUDED.rules_waived,
    status = EXCLUDED.status,
    authored_at = EXCLUDED.authored_at,
    activated_at = EXCLUDED.activated_at,
    superseded_by = EXCLUDED.superseded_by;
