INSERT INTO macro_core.scenario_set (id, week, synthesis, probability_check, swing_variables, rules_waived, status, authored_at, activated_at, superseded_by)
VALUES ('3ff8138c-2e9a-5d5d-9c35-3fa393cec8b0', '2026-W35', 'The week''s driver was the long end and the institutional fight behind it: the 30Y hit a 19-year high the same day gross debt crossed $40T, the Treasury Secretary answered with an off-schedule buyback expansion the market judged insufficient within 48 hours, and what looked like a term-premium story is better read as a Fed-independence discount — which is why the 10Y can sit obediently inside its band while the 30Y goes to 2007 levels. Equities and crypto then traded opposite sides of that same variable: tech duration de-rated on yields while crypto took Wednesday''s yield collapse, a revived CLARITY Act and $2.7B of trapped shorts into a 20% week. This week the calendar hands that conflict a microphone — Warsh''s first Jackson Hole keynote on Aug 28, with core PCE and NVDA stacked on Aug 26 in front of it. The game is not risk-on versus risk-off; it is who controls the long end, and the two books now express that question with opposite signs.', NULL, '["Warsh''s Jackson Hole keynote (Aug 28), his first as Chair: hawkish and institutionally credible — defends Fed primacy over the balance sheet, keeps the hike live — takes the 2Y through 4.35%, de-rates equity duration again and drains gold''s fiscal bid. Deferential or institutionally weak — concedes balance-sheet ground to Treasury, no hike signal — widens the independence discount, sends the 30Y past 5.35% and extends both gold and crypto.","The Aug 26 double-header (core PCE + NVDA): core ≥0.3% into nonfuel import prices at a four-year high and Brent at $94 pushes hike odds through 50% ahead of the SEP; ≤0.2% caps the front end and hands the long end back to fiscal. On NVDA the decay is rotational, not uniform — CoreWeave''s beat-and-raise was bought hard while merchant silicon de-rated on no news, so the swing is whether backlog visibility or unit economics prices the print.","The Iran escalation vector, now financial rather than kinetic: Bessent''s \"economic D-Day\" campaign and secondary sanctions on Chinese refiners convert an oil trade into a US-China trade — escalation with Beijing non-compliant takes Brent past $100 and re-arms the inflation leg. Against that, Pezeshkian''s \"better to end the war now\" is the first genuine de-escalation signal of the war, and China''s refusal caps enforceability. Both tails are wide; do not bound this range again.","Crypto''s vertical entry against its light positioning: F&G ran 31 → 73 in five sessions while majors'' funding stayed at the neutral baseline and coin-terms OI fell. Money holding a $66-70K retest confirms the Phase-1 upgrade; a failure back inside the old box says the whole thing was a squeeze, with Sep 15''s CLARITY vote as the dated resolution."]'::jsonb, ARRAY[]::int[], 'superseded', TIMESTAMPTZ '2026-08-24T00:00:00Z', TIMESTAMPTZ '2026-08-24T00:00:00Z', NULL)
ON CONFLICT (id) DO UPDATE SET
    synthesis = EXCLUDED.synthesis,
    probability_check = EXCLUDED.probability_check,
    swing_variables = EXCLUDED.swing_variables,
    rules_waived = EXCLUDED.rules_waived,
    status = EXCLUDED.status,
    authored_at = EXCLUDED.authored_at,
    activated_at = EXCLUDED.activated_at,
    superseded_by = EXCLUDED.superseded_by;
