INSERT INTO macro_core.scenario_set (id, week, synthesis, probability_check, swing_variables, rules_waived, status, authored_at, activated_at, superseded_by)
VALUES ('f28fbbb6-5193-505c-93c0-e648426f7fef', '2026-W36', 'Warsh replaced the long-end independence fight with a cleaner front-end question: does the labor market justify a September hike? NVIDIA proved exceptional earnings can absorb that repricing, but Russell, breadth, and Marvell show the protection is narrow. The next game is labor plus the AI reward threshold, with oil as the inflation tail and crypto''s light positioning as the cleaner risk-on structure.', NULL, '["Data and Fed sequence: JOLTS and ISM Sep 1–3 feed NFP Sep 4, CPI Sep 11, and the FOMC Sep 15–16; the second JOLTS and PCE Sep 29–30 confirm or reject the resulting regime.","AI reward threshold: Broadcom Sep 2 must deliver NVIDIA-scale visibility; Apple Sep 9, TSMC Sep 10, DevDay Sep 29, and Micron Sep 30 test whether leadership broadens.","Oil, tariffs, and diplomacy: G20 and Section 301 implementation Aug 31–Sep 1, drone tariffs Sep 3, and OPEC+ Sep 6 decide whether Brent stays capped or restores the inflation premium.","Duration, structure, and crypto: Treasury auctions Sep 8–10 and Sep 22–24, CLARITY and the 20Y Sep 15, BOJ/SEC/quad witch Sep 17–18, and the Sep 30 funding deadline map the liquidity path; BTC above $74K with inflows validates Phase 1."]'::jsonb, ARRAY[]::int[], 'superseded', TIMESTAMPTZ '2026-08-31T00:00:00Z', TIMESTAMPTZ '2026-08-31T00:00:00Z', NULL)
ON CONFLICT (id) DO UPDATE SET
    synthesis = EXCLUDED.synthesis,
    probability_check = EXCLUDED.probability_check,
    swing_variables = EXCLUDED.swing_variables,
    rules_waived = EXCLUDED.rules_waived,
    status = EXCLUDED.status,
    authored_at = EXCLUDED.authored_at,
    activated_at = EXCLUDED.activated_at,
    superseded_by = EXCLUDED.superseded_by;
