INSERT INTO macro_core.scenario_set (id, week, synthesis, probability_check, swing_variables, rules_waived, status, authored_at, activated_at, superseded_by)
VALUES ('f7305002-4376-55de-a72d-84dc7dda39b0', '2026-W37', 'The dominant driver has changed from "does labour justify a hike" to "does an oil supply shock the Fed cannot fix arrive before the Fed has decided". Two of the most institutionally central governors have now publicly split from the Chair''s framing, so Aug CPI on Sep 11 and the Sep 15–16 dots are a genuine two-sided event rather than a hawkish formality, while Hormuz has acquired an enforcement mechanism that makes crude an inflation variable with a standing option on becoming a risk variable. Underneath, the equity market is distributing quietly — flat index, falling breadth, unpaid beats — and crypto is doing the same thing in one dimension, holding a level with sponsorship narrowing to BTC alone. This is a week to be positioned for the transmission, not the headline.', 'The ledger''s rolling base case scored 4.0 of the last 8 graded weeks with zero full materializations and a mean Brier of 0.15 over the one scored week, and eight consecutive Partials say the direction has generally been right while the bands have been too narrow. So the base sits at 40% rather than higher — CPI is a binary this journal cannot forecast — and the tail is raised to 25% because the oil leg finally has a named enforcement mechanism and a confirming-regime clause rather than a bare price trigger. R3 and R11 are honoured with an explicit oil row inside every branch and a Brent band sized off the last eight weeks'' $83–$100 range; R4 gates the tail on VIX, HY or breadth; R5 and R9 keep leadership as its own swing variable rather than a rider on the macro call; R6 reserves the dateless shock inside S3; R7 gives crypto its own target row in each branch.', '["August CPI (Sep 11): cool = core ≤0.25%, the hike dies, the front end rallies and breadth gets its first repair window / hot = core ≥0.4%, the hike becomes dominant, the 2Y clears 4.50% and small caps and crypto take the transmission.","The Hormuz permissioning regime and Saudi capacity: cool = an EIA STEO supply revision or a de-escalation returns Brent to the high $80s / hot = the exclusion zone is enforced or a second Aramco outage runs past a week, and Brent prices a physical shortfall rather than a risk premium.","Long-end auction demand (Sep 9–10 cluster, 20Y Sep 15, TIPS Sep 17): cool = auctions stop on the screws and term premium stays contained / hot = a tail with real yields near 2.44% pushes the 30Y through 5.40% and takes duration equities and gold with it.","The AI reward function versus the rates channel: cool = a rewarded beat or a broadening bid repairs leadership after Broadcom went unpaid / hot = the complex keeps trading as pure duration, where NBIS, RIOT and GLXY move on the 10Y and not on their own bookings."]'::jsonb, ARRAY[]::int[], 'superseded', TIMESTAMPTZ '2026-09-09T00:00:00Z', TIMESTAMPTZ '2026-09-09T00:00:00Z', NULL)
ON CONFLICT (id) DO UPDATE SET
    synthesis = EXCLUDED.synthesis,
    probability_check = EXCLUDED.probability_check,
    swing_variables = EXCLUDED.swing_variables,
    rules_waived = EXCLUDED.rules_waived,
    status = EXCLUDED.status,
    authored_at = EXCLUDED.authored_at,
    activated_at = EXCLUDED.activated_at,
    superseded_by = EXCLUDED.superseded_by;
