INSERT INTO macro_core.scenario_set (id, week, synthesis, probability_check, swing_variables, rules_waived, status, authored_at, activated_at, superseded_by)
VALUES ('763905a2-b6ba-5694-9b39-c1026125b5c4', '2026-W38', 'The September hike is no longer the question: at ~86% it is priced, so the game is the dots, and whether a Fed hiking into a 47.8 consumer and a war-driven oil shock is read as credibility or as policy error. Oil has lost its de-escalation catalyst for the second time in four weeks and the swing producer has no output left to offer, so crude stays an inflation variable that keeps the long end pinned near 5%. Underneath a sub-1% index loss, breadth, the Russell, MOVE and futures positioning all moved the way distributions move before they break, while memory, the one AI leg with pricing power, took its first efficiency-narrative hit. This is a week to hold quality and let the dots and quad witching show whether the internals transmit to the index.', 'The ledger''s base case now scores 4.5 of the last 8 graded weeks with 1 full materialization and a mean Brier of 0.35 over two scored weeks, and last week''s 0.545 came from a correct base priced at only 40%. So the base rises to 45%: its hike leg is already ~86% priced and its oil leg has lost its only near-term de-escalation catalyst, but it stays under 50% because the dots are a genuine binary. R2 and R11 are met with oil two-sided across S1 and S2 and its own band in every branch, sized off the last eight weeks'' $83–$108 Brent range per R3; R4 gates S3 on VIX, HY or breadth; R5 and R9 keep memory as a swing variable rather than a rider on the index call; R6 reserves the dateless model-efficiency and funding shocks inside S3; R7 gives crypto its own row; R10 keeps both the BTC outflow run and ETH''s one-day inflow out of the base-case targets. The base is labelled S1 because it is the most likely branch; the ledger''s S2 habit is a labelling artefact, not a reason to reorder.', '["The Sep 16 dots and press conference: cool = a hike framed as insurance with the median dot showing no more than one further move, which rallies the 2Y and the Russell / hot = two more dots or an October signal, taking the 2Y through 4.75% and the 10Y through 5%.","The Hormuz channel after the postponed Oman meeting: cool = the meeting is rescheduled or a shipping-lane arrangement is announced and Brent returns under $98 / hot = a further tanker wave or new Saudi shut-ins take Brent through $110 with no OPEC+ offset before Oct 4.","Memory versus the efficiency narrative: cool = Micron''s AI Infra Summit comments and TSMC data hold HBM demand and MU and SKHY recover the Sep 10 loss / hot = a second efficiency release or a hyperscaler capex trim turns the DeepSeek reversal into the crowded-AI unwind on Blackswan Events.","BTC ETF flows versus ETH''s bid: cool = BTC outflows stop and ETH''s inflow repeats, lifting both / hot = a second BTC outflow week while ETH''s one-day bid fails, which is the path to the $74K falsifier."]'::jsonb, ARRAY[]::int[], 'superseded', TIMESTAMPTZ '2026-09-14T00:00:00Z', TIMESTAMPTZ '2026-09-14T00:00:00Z', NULL)
ON CONFLICT (id) DO UPDATE SET
    synthesis = EXCLUDED.synthesis,
    probability_check = EXCLUDED.probability_check,
    swing_variables = EXCLUDED.swing_variables,
    rules_waived = EXCLUDED.rules_waived,
    status = EXCLUDED.status,
    authored_at = EXCLUDED.authored_at,
    activated_at = EXCLUDED.activated_at,
    superseded_by = EXCLUDED.superseded_by;
