INSERT INTO macro_core.scenario_set (id, week, synthesis, probability_check, swing_variables, rules_waived, status, authored_at, activated_at, superseded_by)
VALUES ('22315d4d-15f3-590b-b57d-6b009f83625f', '2026-W39', 'The Fed hiked into a 5% ten-year and a closed Hormuz, and the risk complex answered by sending the VIX to a run low and tightening investment-grade spreads, which is the week''s real information: nothing that prices risk is treating the macro as a risk. What is pricing it is the index''s composition, where breadth broke 50%, the Dow lost a third straight week, and the only leg working is a memory trade whose shortage was confirmed by its largest buyer rather than by its sellers. Crypto broke $80K off an entirely different driver, so the two books are no longer trading the same variable and should not share a scenario row. The week ahead settles it in two places: whether the Sep 22–24 auctions repeat the 20Y''s record tail, and whether Micron on Sep 30 can carry a complex into which nine of every ten incremental AI dollars now flow.', 'The ledger''s base case scores 4.5 of the last 8 graded weeks with only 1 full materialization and a mean Brier of 0.27 across three scored weeks, and last week''s 0.105 was the best of that record — a correctly-priced base whose only misses were composition. The record says the habit is a base that is directionally right and half-graded, which argues for tighter bands rather than a higher probability. The base stays at 45%: its rates, credit and breadth legs all extend a trend that three consecutive weeks have confirmed, but it cannot go higher while the Sep 22–24 cluster and Micron are both unresolved and both genuinely binary. S2 is lifted to 32% because the 20Y''s record tail is the first hard evidence behind a tail-risk item that had only commentary behind it, and because a VIX of 14.81 makes the repricing distance larger than usual. R2 and R11 are met with oil two-sided across all three branches and its own band in each, sized off the last eight weeks'' $83–$108 Brent range per R3. R4 gates S2 on VIX, HY or breadth. R5 gives leadership its own line in every branch after last week''s miss. R6 reserves the dateless shocks inside S2. R7 and R12 give crypto its own row priced off the regulatory channel that actually moved it, not off rates. R10 keeps the two-session BTC inflow run out of the base case''s flow target.', '["The Sep 22–24 2Y/5Y/7Y cluster, after the 20Y tailed 2 bp at a record 5.42%: cool = the cluster clears near where-issued and the 10Y falls back under 4.95% / hot = a second tail with the 10Y through 5.12% and the 2Y through 4.90%, which is demand failing rather than price adjusting.","Micron Q4 FY2026 on Sep 30, now the whole complex''s print: cool = HBM pricing and a raised guide confirm Intel''s shortage framing and memory pulls breadth up with it / hot = any sign of customer pushback on five-to-sevenfold memory prices turns the index''s only working leg into the crowded-AI unwind on Blackswan Events.","Oil as the East-West line restores into OPEC+ on Oct 4: cool = full restoration or an Oman reschedule takes Brent under $92 and pulls the inflation leg out of the October decision / hot = the Sep 19 Houthi pattern reaches the repaired line, or Hormuz enforcement returns, and Brent clears $115.","The Oct 28 hike, priced at a coin flip, against PCE on Sep 30 and NFP on Oct 2: cool = core PCE at 0.2% with payrolls under 125K pushes October back to a hold and the 2Y under 4.70% / hot = 0.3% with firm payrolls takes October past 70% and validates the 2027 dots."]'::jsonb, ARRAY[]::int[], 'active', TIMESTAMPTZ '2026-09-21T00:00:00Z', TIMESTAMPTZ '2026-09-21T00:00:00Z', NULL)
ON CONFLICT (id) DO UPDATE SET
    synthesis = EXCLUDED.synthesis,
    probability_check = EXCLUDED.probability_check,
    swing_variables = EXCLUDED.swing_variables,
    rules_waived = EXCLUDED.rules_waived,
    status = EXCLUDED.status,
    authored_at = EXCLUDED.authored_at,
    activated_at = EXCLUDED.activated_at,
    superseded_by = EXCLUDED.superseded_by;
