INSERT INTO macro_core.strategy (id, week, asset, stance, posture, exposure_lo, exposure_hi, exposure_operated_lo, exposure_operated_hi, status, authored_at, activated_at, superseded_by)
VALUES ('84040c26-a23a-5c52-9b99-e1e0ceac7f21', '2026-W32', 'crypto', 'Selective accumulation - majors only, at the box low, and smaller than last week.', 'Hold, leaning reduce. Phase 5 held on level, but tracker condition 3 went from absent to refuted and the ETF flow that had been confirming the floor turned against it. Nothing broke; the case got thinner.', 0, 25, 10, 15, 'superseded', TIMESTAMPTZ '2026-08-03T00:00:00Z', TIMESTAMPTZ '2026-08-03T00:00:00Z', NULL)
