INSERT INTO macro_core.strategy (id, week, asset, stance, posture, exposure_lo, exposure_hi, exposure_operated_lo, exposure_operated_hi, status, authored_at, activated_at, superseded_by)
VALUES ('f329506b-f4db-5837-bbb7-a7b4f2280360', '2026-W32', 'equities', 'Selective - long the monetisers, avoid the spenders, and no index bet until the record zone above 7,550 resolves.', 'Hold. Phase 3 with zero of four Stage-4 conditions met and a rising 200dma sitting 6.6% below: the structure is not bearish. But breadth rolled over inside an up week and the entire index gain is two names wide, so it is not a buy either. Neither adding nor cutting is what the evidence supports.', 25, 50, 30, 40, 'superseded', TIMESTAMPTZ '2026-08-03T00:00:00Z', TIMESTAMPTZ '2026-08-03T00:00:00Z', NULL)
ON CONFLICT (id) DO UPDATE SET
    stance = EXCLUDED.stance,
